@Component("territory-handler")
@ProcessingGroup("territory-processing-group")
public class TerritoryEventHandler {
	
	// core constructor
	TerritoryEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTerritoryEvent
     */
    @EventHandler
    public void handle( CreateTerritoryEvent event) {
        entityManager.persist(new Territory(event.getTerritoryId(), event.getName(), event.getRegion(), event.getOrganization(), event.getAccounts(), event.getUsers(), event.getTerritoryType()));
    }

    /*
     * @param	event UpdateTerritoryEvent
     */
    @EventHandler
    public Territory handle( UpdateTerritoryEvent event) {
    	entityManager.merge(new Territory(event.getTerritoryId(), event.getName(), event.getRegion(), event.getOrganization(), event.getAccounts(), event.getUsers(), event.getTerritoryType()));
    }
    
    /*
     * @param	event DeleteTerritoryEvent
     */
    @EventHandler
    public void on( DeleteTerritoryEvent event) {
    	Territory entity = new Territory();
   
    	// ------------------------------------------
    	// apply the TerritoryId
    	// ------------------------------------------
    	entity.setTerritoryId( event.getTerritoryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TerritoryRepository territoryEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TerritoryEventHandler.class.getName());

}
